using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.Splines;using Unity.Mathematics;using UnityEditor;using UnityEditor.SceneManagement;using LWS.TruckSports;using LWS.TruckSports.Editor;
namespace LWS.TruckSkyTow.Editor {
public static class SkyTowAuthoring {
 public const string Folder="TruckSkyTow",Scene="Assets/TruckSkyTow/Scenes/TruckSkyTow.unity";static Material navy,white,coral,ice,gold,cable;static PhysicsMaterial contact;
 [MenuItem("Truck Sports/Sky Tow/Create original Arctic course")]
 public static void Create(){if(File.Exists(Scene))throw new InvalidOperationException("Preserve the existing authored Sky Tow scene; use targeted upgrades.");var m=SportsEventAuthoring.Begin<SkyTowMatch>(Folder);Directory.CreateDirectory("Assets/TruckSkyTow/Art");m.setup.count=4;m.option=1;m.NormalizeSetup();for(int i=1;i<4;i++)m.setup.players[i].source=LWS.TruckBowling.BowlingSource.AI;m.feedback.clips=LWS.TruckHockey.Editor.HockeyAudioAuthoring.Create();contact=SportsEventAuthoring.Contact(Folder,"Actual ice and ring contact",.25f,.08f);navy=SportsEventAuthoring.Mat(Folder,"Arctic marine navy",new Color(.025f,.09f,.15f),.55f);white=SportsEventAuthoring.Mat(Folder,"Expedition warm white",new Color(.72f,.8f,.82f),.25f);coral=SportsEventAuthoring.Mat(Folder,"Expedition safety coral",new Color(.94f,.19f,.075f),.4f);ice=SportsEventAuthoring.Mat(Folder,"Deep glacier blue",new Color(.15f,.51f,.64f),.38f);gold=SportsEventAuthoring.Mat(Folder,"Gold bonus rings",new Color(1,.57f,.035f),.65f);gold.EnableKeyword("_EMISSION");gold.SetColor("_EmissionColor",new Color(1,.36f,.015f)*.6f);cable=SportsEventAuthoring.Mat(Folder,"Braided tow cable",new Color(.08f,.11f,.14f),.35f);
  var course=new GameObject("Authored six-section Arctic tow course").AddComponent<SkyTowCourse>();m.course=course;course.route=course.gameObject.AddComponent<SplineContainer>();var points=new[]{new Vector3(0,0,0),new Vector3(0,0,160),new Vector3(90,0,340),new Vector3(240,0,480),new Vector3(280,0,680),new Vector3(120,0,870),new Vector3(-90,0,960),new Vector3(-240,0,1160),new Vector3(-190,0,1360),new Vector3(30,0,1490),new Vector3(240,0,1640),new Vector3(300,0,1860),new Vector3(190,0,2050),new Vector3(-40,0,2190),new Vector3(-130,0,2390)};course.route.Spline=new Spline(points.Select(p=>new BezierKnot((float3)p)),false);course.route.Spline.SetTangentMode(TangentMode.AutoSmooth);course.length=course.route.CalculateLength();course.duration=120;Terrain(course);Water(course);InstallLanes(course);
  var ringMesh=Torus("Original precision ring",4.8f,.15f,48,8);course.rings=new SkyTowRing[144];for(int slot=0;slot<4;slot++)for(int i=0;i<36;i++){float at=course.LaneDuration(slot)*(.07f+i*(.88f/35));var center=course.NominalTruck(at,slot);course.Frame(at,slot,out var p,out var rotation);float offset=i<5?0:Mathf.Sin(i*1.45f)*(i>21?3:1.8f);center+=rotation*Vector3.right*offset+Vector3.up*(i<5?0:Mathf.Sin(i*.83f)*2);var g=new GameObject("Physical "+(i%6==5?"GOLD ":"")+"ring "+(i+1)+" course "+(slot+1));g.transform.SetPositionAndRotation(center,rotation);var ring=g.AddComponent<SkyTowRing>();ring.slot=slot;ring.index=i;ring.at=at;ring.bonus=i%6==5;g.AddComponent<MeshFilter>().sharedMesh=ringMesh;ring.art=g.AddComponent<MeshRenderer>();ring.art.sharedMaterial=ring.bonus?gold:coral;// Luminous score gates are non-solid; actual whole-body swept geometry owns clearance.
   course.rings[slot*36+i]=ring;}
  var boatMesh=Hull();m.racers=new SkyTowRacer[4];var trucks=new SportsEventTruck[4];for(int i=0;i<4;i++){course.Frame(0,i,out var p,out var q);var t=SportsEventAuthoring.Truck(m,Folder,"Towed expedition truck "+(i+1),p+q*new Vector3(0,18,-29),i);SportsRallyAuthoring.FitTruck(t);t.body.linearDamping=.015f;t.body.angularDamping=.25f;t.body.maxAngularVelocity=5;t.body.solverIterations=16;var r=t.gameObject.AddComponent<SkyTowRacer>();m.racers[i]=r;trucks[i]=t;r.match=m;r.truck=t;r.slot=i;r.ropeLength=35;r.liftControlRange=.9f;r.boat=Boat(i,boatMesh,out r.propeller);r.boat.position=p;r.boat.rotation=q;var joint=t.gameObject.AddComponent<ConfigurableJoint>();r.tether=joint;joint.connectedBody=r.boat;joint.autoConfigureConnectedAnchor=false;joint.anchor=new Vector3(0,1.25f,.2f);joint.connectedAnchor=new Vector3(0,1,-1);joint.xMotion=joint.yMotion=joint.zMotion=ConfigurableJointMotion.Limited;joint.linearLimit=new SoftJointLimit{limit=35,contactDistance=.05f};joint.linearLimitSpring=new SoftJointLimitSpring{spring=0,damper=0};joint.projectionMode=JointProjectionMode.None;joint.projectionDistance=.25f;joint.enableCollision=false;var line=new GameObject("Actual taut tow cable "+i).AddComponent<LineRenderer>();line.positionCount=2;line.useWorldSpace=true;line.widthMultiplier=.07f;line.sharedMaterial=cable;r.cable=line;Sail(t.transform);}
  m.views=SportsRallyAuthoring.Views(m,trucks);m.views.groundOffset=new Vector3(0,7,-16);m.atmosphere=SportsChaosAuthoring.Weather(m,Folder);m.views.weather=m.atmosphere;m.presets=SportsWeatherPresetsAuthoring.EnsureCatalog();m.atmosphere.presets=m.presets;SportsWeatherRenderingAuthoring.Install(m,Folder);foreach(var camera in m.views.views){camera.view.farClipPlane=10000;camera.view.clearFlags=CameraClearFlags.Skybox;}m.views.broadcast.view.farClipPlane=10000;Scenery(course);SportsEventAuthoring.UI(m);SportsRallyAuthoring.CompactUI(m);SportsWeatherPickerAuthoring.Install(m,m.presets,new Vector2(0,305));foreach(var text in m.menus.pages[0].GetComponentsInChildren<TMPro.TMP_Text>(true))if(text.name=="Weather selection explanation"||text.name=="Weather selection label")text.gameObject.SetActive(false);SportsBroadcastAuthoring.ApplyScene();SportsEventAuthoring.Save(Folder);SkyTowPresentationAuthoring.Install(m);EditorSceneManager.SaveScene(m.gameObject.scene);AssetDatabase.SaveAssets();Validate();Debug.Log("SKYTOW_CREATED length="+course.length+" duration="+course.duration);}
 static void InstallLanes(SkyTowCourse course){if(course.laneRoutes!=null&&course.laneRoutes.Length==4)return;var samples=new Vector3[4][];for(int slot=0;slot<4;slot++){samples[slot]=new Vector3[72];for(int i=0;i<72;i++)course.Frame(i*course.duration/71f,slot,out samples[slot][i],out var rotation);}course.laneRoutes=new SplineContainer[4];course.laneLengths=new float[4];for(int slot=0;slot<4;slot++){var root=new GameObject("Authored constant-speed tow lane "+slot);root.transform.SetParent(course.transform,false);var path=root.AddComponent<SplineContainer>();path.Spline=new Spline(samples[slot].Select(p=>new BezierKnot((float3)p)),false);path.Spline.SetTangentMode(TangentMode.AutoSmooth);course.laneRoutes[slot]=path;course.laneLengths[slot]=path.CalculateLength();}}
 public static void UpgradeLanes(){EditorSceneManager.OpenScene(Scene);var m=UnityEngine.Object.FindAnyObjectByType<SkyTowMatch>();foreach(var ring in m.course.rings){var old=ring.GetComponent<Collider>();if(old!=null)UnityEngine.Object.DestroyImmediate(old);}InstallLanes(m.course);foreach(var racer in m.racers){racer.liftControlRange=.9f;racer.tether.linearLimitSpring=new SoftJointLimitSpring{spring=0,damper=0};racer.tether.projectionMode=JointProjectionMode.None;racer.tether.projectionDistance=.25f;}for(int slot=0;slot<4;slot++)for(int i=0;i<36;i++){var ring=m.course.Ring(slot,i);float at=m.course.LaneDuration(slot)*(.07f+i*(.88f/35));m.course.Frame(at,slot,out var p,out var rotation);float offset=i<5?0:Mathf.Sin(i*1.45f)*(i>21?3:1.8f);ring.at=at;ring.transform.SetPositionAndRotation(m.course.NominalTruck(at,slot)+rotation*Vector3.right*offset+Vector3.up*(i<5?0:Mathf.Sin(i*.83f)*2),rotation);}EditorSceneManager.MarkSceneDirty(m.gameObject.scene);EditorSceneManager.SaveScene(m.gameObject.scene);AssetDatabase.SaveAssets();Debug.Log("SKYTOW_CONSTANT_SPEED lanes="+string.Join(",",m.course.laneLengths.Select(v=>v/m.course.Cruise)));}
 static void Terrain(SkyTowCourse course){var data=new TerrainData{name="Authored Arctic fjord terrain"};data.heightmapResolution=257;data.size=new Vector3(2200,280,3200);var heights=new float[257,257];var samples=new Vector3[180];for(int i=0;i<samples.Length;i++){course.Frame(i*120f/(samples.Length-1),0,out samples[i],out var q);samples[i]+=q*Vector3.right*21;}for(int z=0;z<257;z++)for(int x=0;x<257;x++){Vector3 p=new Vector3(x/256f*2200-1100,0,z/256f*3200-400);float closest=float.MaxValue;foreach(var sample in samples)closest=Mathf.Min(closest,(p-sample).sqrMagnitude);float distance=Mathf.Sqrt(closest);float ridge=Mathf.SmoothStep(0,1,Mathf.InverseLerp(85,240,distance));float mountain=(65+Mathf.PerlinNoise(p.x*.003f+6,p.z*.003f+9)*160)*ridge;heights[z,x]=Mathf.Clamp01((mountain+7)/280);}data.SetHeights(0,0,heights);var source=AssetDatabase.LoadAssetAtPath<TerrainLayer>("Assets/PinwheelStudio/Vista/Personal/Samples/TerrainLayers/RockFace/RockFace_VistaSample.terrainlayer");var layer=UnityEngine.Object.Instantiate(source);layer.name="Arctic snow rock · owned Vista layer";layer.diffuseRemapMin=new Vector4(.2f,.29f,.34f,0);layer.diffuseRemapMax=new Vector4(.82f,.9f,.95f,1);layer.tileSize=Vector2.one*30;AssetDatabase.CreateAsset(layer,"Assets/TruckSkyTow/Art/Arctic terrain layer.terrainlayer");data.terrainLayers=new[]{layer};AssetDatabase.CreateAsset(data,"Assets/TruckSkyTow/Art/Arctic fjord terrain.asset");var terrain=UnityEngine.Terrain.CreateTerrainGameObject(data).GetComponent<Terrain>();terrain.name="Continuous carved navigable fjord and enormous snowy mountains";terrain.transform.position=new Vector3(-1100,-15,-400);terrain.drawInstanced=true;terrain.heightmapPixelError=8;terrain.basemapDistance=1700;var mat=SportsEventAuthoring.Mat(Folder,"Arctic Vista terrain",Color.white);mat.shader=Shader.Find("Universal Render Pipeline/Terrain/Lit");terrain.materialTemplate=mat;course.terrain=terrain;}
 static void Water(SkyTowCourse c){var plane=GameObject.CreatePrimitive(PrimitiveType.Plane);plane.name="Continuous Arctic water · existing River Modeler material";plane.transform.position=new Vector3(0,.15f,1200);plane.transform.localScale=new Vector3(220,1,320);UnityEngine.Object.DestroyImmediate(plane.GetComponent<Collider>());var source=AssetDatabase.LoadAssetAtPath<Material>("Assets/TruckBogSnorkelling/Materials/Bog vendor water surface.mat");if(source==null)throw new InvalidOperationException("Verified existing river surface required");var water=UnityEngine.Object.Instantiate(source);water.name="Arctic River Modeler surface";AssetDatabase.CreateAsset(water,"Assets/TruckSkyTow/Materials/Arctic river.mat");plane.GetComponent<Renderer>().sharedMaterial=water;c.water=plane.transform;}
 static Rigidbody Boat(int i,Mesh mesh,out Transform propeller){var root=new GameObject("Original expedition powerboat "+(i+1));root.AddComponent<MeshFilter>().sharedMesh=mesh;root.AddComponent<MeshRenderer>().sharedMaterial=navy;var body=root.AddComponent<Rigidbody>();body.isKinematic=true;body.interpolation=RigidbodyInterpolation.Interpolate;var shape=root.AddComponent<BoxCollider>();shape.center=new Vector3(0,0,0);shape.size=new Vector3(3.7f,1.4f,8.5f);shape.sharedMaterial=contact;SportsEventAuthoring.Box("Marine raised deck",new Vector3(0,.65f,-.1f),new Vector3(3.2f,.18f,5.7f),white,null,root.transform);SportsEventAuthoring.Box("Expedition wheelhouse",new Vector3(0,1.3f,.8f),new Vector3(2.5f,1.2f,2.8f),coral,null,root.transform);SportsEventAuthoring.Box("Smoked bridge windshield",new Vector3(0,1.62f,2.22f),new Vector3(2.25f,.48f,.035f),navy,null,root.transform);SportsEventAuthoring.Box("Wheelhouse roof",new Vector3(0,1.95f,.8f),new Vector3(2.9f,.2f,3.1f),white,null,root.transform);propeller=new GameObject("Visible marine propeller").transform;propeller.SetParent(root.transform,false);propeller.localPosition=new Vector3(0,-.25f,-4.5f);for(int blade=0;blade<3;blade++){var p=SportsEventAuthoring.Box("Propeller blade",new Vector3(0,.45f,0),new Vector3(.28f,1,.08f),coral,null,propeller);p.transform.RotateAround(propeller.position,propeller.forward,blade*120);}return body;}
 static void Sail(Transform truck){var root=new GameObject("Functional aerodynamic tow sail").transform;root.SetParent(truck,false);root.localPosition=new Vector3(0,3.2f,0);var mesh=new Mesh{name="Original curved tow sail"};var vertices=new List<Vector3>();var uv=new List<Vector2>();var triangles=new List<int>();for(int x=0;x<=12;x++)for(int z=0;z<2;z++){float px=x/12f*6-3;vertices.Add(new Vector3(px,-px*px*.025f,z*2-1));uv.Add(new Vector2(x/12f,z));}for(int x=0;x<12;x++){int a=x*2;triangles.AddRange(new[]{a,a+1,a+2,a+1,a+3,a+2,a+2,a+1,a,a+2,a+3,a+1});}mesh.SetVertices(vertices);mesh.SetUVs(0,uv);mesh.SetTriangles(triangles,0);mesh.RecalculateNormals();AssetDatabase.CreateAsset(mesh,"Assets/TruckSkyTow/Art/Tow sail "+truck.name+".asset");root.gameObject.AddComponent<MeshFilter>().sharedMesh=mesh;root.gameObject.AddComponent<MeshRenderer>().sharedMaterial=coral;for(int side=-1;side<=1;side+=2){var strap=new GameObject("Tow sail strap").AddComponent<LineRenderer>();strap.transform.SetParent(truck,false);strap.useWorldSpace=false;strap.positionCount=2;strap.SetPosition(0,new Vector3(side*.6f,.9f,0));strap.SetPosition(1,new Vector3(side*3,2.97f,0));strap.widthMultiplier=.035f;strap.sharedMaterial=cable;}}
 static Mesh Hull(){var mesh=new Mesh{name="Original seven-section expedition powerboat hull"};var vertices=new List<Vector3>();var uv=new List<Vector2>();var tri=new List<int>();float[] widths={.8f,1.8f,2,1.95f,1.5f,.7f,.02f};for(int i=0;i<widths.Length;i++){float w=widths[i],z=-4.5f+i*1.5f;var section=new[]{new Vector3(-w,.4f,z),new Vector3(-w*.8f,-.4f,z),new Vector3(0,-.8f,z),new Vector3(w*.8f,-.4f,z),new Vector3(w,.4f,z),new Vector3(0,.65f,z)};for(int j=0;j<6;j++){vertices.Add(section[j]);uv.Add(new Vector2(j/6f,i/6f));}}for(int i=0;i<6;i++)for(int j=0;j<6;j++){int a=i*6+j,b=i*6+(j+1)%6;tri.AddRange(new[]{a,b,a+6,b,b+6,a+6});}for(int j=1;j<5;j++){tri.AddRange(new[]{0,j+1,j});tri.AddRange(new[]{36,36+j,37+j});}mesh.SetVertices(vertices);mesh.SetUVs(0,uv);mesh.SetTriangles(tri,0);mesh.RecalculateNormals();AssetDatabase.CreateAsset(mesh,"Assets/TruckSkyTow/Art/Original expedition boat hull.asset");return mesh;}
 internal static Mesh Torus(string name,float radius,float tube,int sides,int rings){var mesh=new Mesh{name=name};var v=new Vector3[sides*rings];var uv=new Vector2[v.Length];var triangles=new int[sides*rings*6];for(int a=0;a<sides;a++)for(int b=0;b<rings;b++){float angle=a*Mathf.PI*2/sides,minor=b*Mathf.PI*2/rings,r=radius+Mathf.Cos(minor)*tube;int i=a*rings+b;v[i]=new Vector3(Mathf.Cos(angle)*r,Mathf.Sin(angle)*r,Mathf.Sin(minor)*tube);uv[i]=new Vector2(a/(float)sides,b/(float)rings);int next=(a+1)%sides*rings,j=(b+1)%rings;int k=i*6;triangles[k]=i;triangles[k+1]=next+b;triangles[k+2]=a*rings+j;triangles[k+3]=a*rings+j;triangles[k+4]=next+b;triangles[k+5]=next+j;}mesh.vertices=v;mesh.uv=uv;mesh.triangles=triangles;mesh.RecalculateNormals();AssetDatabase.CreateAsset(mesh,"Assets/TruckSkyTow/Art/"+name+".asset");return mesh;}
 static void Scenery(SkyTowCourse c){var root=new GameObject("Six composed Arctic landmarks · installed owned assets").transform;for(int section=0;section<6;section++){float time=10+section*20;c.Frame(time,0,out var p,out var q);p+=q*Vector3.right*21;for(int side=-1;side<=1;side+=2){for(int i=0;i<8;i++){Vector3 at=p+q*new Vector3(side*(115+i%3*28),0,(i-3.5f)*24);at.y=c.terrain.SampleHeight(at)+c.terrain.transform.position.y;var holder=new GameObject("Glacial cliff formation "+section+" "+side+" "+i).transform;holder.SetParent(root);holder.position=at;LWS.TruckKeepaway.Editor.KeepawayPresentationAuthoring.Fit(holder,"Assets/Toon Gas Station/Prefabs/Rock_Cluster_1A.prefab",new Vector3(45+i%3*9,35+i%4*12,40),0);foreach(var renderer in holder.GetComponentsInChildren<Renderer>())renderer.sharedMaterial=i%3==0?white:ice;if(section==0||section==3)for(int tree=0;tree<3;tree++){var t=at+q*new Vector3(side*(25+tree*10),0,tree*13);t.y=c.terrain.SampleHeight(t)+c.terrain.transform.position.y;SportsRallyAuthoring.Prop(root,"Assets/PinwheelStudio/Vista/Personal/Samples/Prefabs/VistaSample_PineTree.prefab",t,new Vector3(8,18,8));}}}
  if(section==0||section==4)for(int i=0;i<8;i++){var at=p+q*new Vector3(135+i%2*22,0,(i-3.5f)*22);at.y=c.terrain.SampleHeight(at)+c.terrain.transform.position.y;SportsRallyAuthoring.Prop(root,section==0?"Assets/JC_LP_MegaCity/Prefabs/Buildings/SM_Buildings_House_06_V1.prefab":"Assets/JC_LP_MegaCity/Prefabs/Buildings/SM_Buildings_Warehouse_01.prefab",at,section==0?new Vector3(18,16,20):new Vector3(30,22,35));if(section==4)SportsRallyAuthoring.Prop(root,"Assets/ShipContainerPack/URP/Prefabs/ShipContainerRed_URP.prefab",at+q*new Vector3(-12,0,10),new Vector3(12,3,3));}
  if(section==1||section==2||section==5)for(int i=0;i<9;i++){var at=p+q*new Vector3((i%2==0?-1:1)*(65+i%3*9),-.6f,(i-4)*17);var holder=new GameObject("Floating detailed iceberg "+i).transform;holder.SetParent(root);holder.position=at;LWS.TruckKeepaway.Editor.KeepawayPresentationAuthoring.Fit(holder,"Assets/PinwheelStudio/Vista/Personal/Samples/Prefabs/VistaSample_DesertRock.prefab",new Vector3(12+i%3*5,8+i%4*4,16),0);foreach(var renderer in holder.GetComponentsInChildren<Renderer>())renderer.sharedMaterial=ice;}
 }
 }
 public static void Validate(){var m=UnityEngine.Object.FindAnyObjectByType<SkyTowMatch>();if(m==null||m.racers.Length!=4||m.course.rings.Length!=144||m.course.length<1500||m.course.duration<110||m.course.duration>130||m.course.terrain==null||m.course.water==null)throw new InvalidOperationException("Sky Tow scene/course incomplete.");foreach(var r in m.racers)if(r.boat==null||r.tether==null||r.truck==null||r.cable==null)throw new InvalidOperationException("Sky Tow requires physical trucks, boats and tow cables.");if(UnityEngine.Object.FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length!=1)throw new InvalidOperationException("One Sky Tow listener required.");}
}
